function sourceTransform(e,a,o){const base=e.dataset.originalTransform||'';if(!a?.sourceSize)return `translate(${o.x} ${o.y}) ${base}`;const b=a.sourceBox,d=a.sourceSize,cx=b.x+b.width/2,cy=b.y+b.height/2;return `translate(${o.x} ${o.y}) ${base} translate(${cx} ${cy}) rotate(${d.rotation}) scale(${d.width/b.width} ${d.height/b.height}) translate(${-cx} ${-cy})`;}
function sourceSizeEditor(panel,a){const feature=features.get(a.id)?.e;let b=a.sourceBox;if(!b&&feature){const q=feature.getBBox();b={x:q.x,y:q.y,width:q.width,height:q.height};}if(!b||!b.width||!b.height)return;const d=a.sourceSize||{width:b.width,height:b.height,rotation:0};const form=el('form',undefined,'landscape-editor');form.append(el('h3','Size & shape'),el('small','Resize the existing outline. Approximate map metres; original shape is preserved.'));const inputs={};for(const [key,title,min,max]of [['width','Width',.1,5000],['height','Length',.1,5000],['rotation','Rotation (degrees)',-360,360]]){const i=field(form,title,'input','source-'+key);i.type='number';i.min=min;i.max=max;i.step='any';i.required=true;i.value=d[key];inputs[key]=i;}const save=el('button','Save size & rotation','button green');save.type='submit';form.append(save);const prepare=dimensions=>{try{M.resizeSource(state,selected,dimensions,b,actor());pendingMove=null;pendingAdd=null;pendingLandscape={info:{...selected},dimensions,sourceBox:{...b}};$('move-warning-heading').textContent='Resize this existing feature on all maps?';$('move-warning').querySelectorAll('p')[1].textContent='The existing outline will resize and rotate on the overview, hole maps and prints. The original map is retained; you can undo or restore this size.';$('move-warning').showModal();}catch(err){message(err.message);}};form.onsubmit=e=>{e.preventDefault();prepare({width:Number(inputs.width.value),height:Number(inputs.height.value),rotation:Number(inputs.rotation.value)});};if(a.sourceSize){const reset=el('button','Restore original size','button outline');reset.type='button';reset.onclick=()=>prepare({width:b.width,height:b.height,rotation:0});form.append(reset);}panel.append(form);}
function landscapeTransform(g,o={x:0,y:0}){return `translate(${g.x+o.x} ${g.y+o.y}) rotate(${g.rotation}) scale(${g.width} ${g.height})`;}
function landscapeSymbol(a){const g=svgEl('g',{id:a.id,'data-landscape':a.type,transform:landscapeTransform(a.geometry),'aria-label':a.type+' '+a.label});const palette={Tree:['#638354','#344f36'],Shrub:['#8da16b','#5d784a'],'Flower bed':['#be806e','#825944'],'Sand trap':['#eddbaf','#b9a470'],'Water hazard':['#80adb8','#507f90']}[a.type];const base=svgEl('path',{'data-landscape-fill':'true',d:'',fill:palette[0],stroke:palette[1],'stroke-width':'.025','vector-effect':'none'});g.append(base);updateLandscapeShape(g,a.geometry);if(a.type==='Tree'||a.type==='Shrub'){for(const [x,y,r,fill]of [[-.2,-.12,.24,'#aac08a'],[.17,-.15,.28,palette[0]],[.08,.19,.24,'#91ab75']])g.append(svgEl('circle',{cx:x,cy:y,r,fill,opacity:'.6','pointer-events':'none'}));}if(a.type==='Flower bed'){for(const [x,y]of [[-.27,-.17],[0,.13],[.26,-.13],[-.2,.18],[.28,.19]])g.append(svgEl('circle',{cx:x,cy:y,r:'.065',fill:'#f4cf9b','pointer-events':'none'}));}return g;}
